def merge_intervals(iv: list[tuple[float, float]]) -> list[tuple[float, float]]:
    if not iv:
        return []

    # Sort intervals by start value to ensure sequential processing
    sorted_iv = sorted(iv, key=lambda x: x[0])

    merged = []

    for start, end in sorted_iv:
        # Requirement: Interval with start > end must raise ValueError
        if start > end:
            raise ValueError("Start of interval cannot be greater than end.")

        if not merged:
            merged.append((start, end))
        else:
            prev_start, prev_end = merged[-1]
            # If the current interval overlaps or touches the previous one
            if start <= prev_end:
                # Merge by updating the end of the last interval in the list
                merged[-1] = (prev_start, max(prev_end, end))
            else:
                # No overlap, add as a new interval
                merged.append((start, end))

    return merged

from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("Capacity must be greater than 0.")
        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key):
        if key not in self.cache:
            return -1
        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key, value):
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

import heapq

def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    all_nodes = set(deps.keys())
    for dependencies in deps.values():
        all_nodes.update(dependencies)

    adj = {node: [] for node in all_nodes}
    in_degree = {node: 0 for node in all_nodes}

    for node, dependencies in deps.items():
        for dep in dependencies:
            adj[dep].append(node)
            in_degree[node] += 1

    heap = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected in dependencies")

    return result

def evaluate(expr: str) -> float:
    def tokenize(s):
        tokens = []
        i = 0
        while i < len(s):
            if s[i].isspace():
                i += 1
                continue
            if s[i].isdigit() or s[i] == '.':
                start = i
                dots = 0
                while i < len(s) and (s[i].isdigit() or s[i] == '.'):
                    if s[i] == '.':
                        dots += 1
                    i += 1
                if dots > 1:
                    raise ValueError("Syntax error")
                num_str = s[start:i]
                try:
                    tokens.append(float(num_str))
                except ValueError:
                    raise ValueError("Syntax error")
            elif s[i] in "+-*/()":
                tokens.append(s[i])
                i += 1
            else:
                raise ValueError("Syntax error")
        return tokens

    tokens = tokenize(expr)
    if not tokens:
        raise ValueError("Syntax error")

    pos = 0

    def peek():
        nonlocal pos
        return tokens[pos] if pos < len(tokens) else None

    def consume(expected=None):
        nonlocal pos
        t = peek()
        if t is None:
            raise ValueError("Syntax error")
        if expected is not None and t != expected:
            raise ValueError("Syntax error")
        pos += 1
        return t

    def parse_expression():
        node = parse_term()
        while peek() in ('+', '-'):
            op = consume()
            right = parse_term()
            if op == '+':
                node += right
            else:
                node -= right
        return node

    def parse_term():
        node = parse_factor()
        while peek() in ('*', '/'):
            op = consume()
            right = parse_factor()
            if op == '*':
                node *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                node /= right
        return node

    def parse_factor():
        if peek() == '-':
            consume('-')
            return -parse_factor()
        return parse_primary()

    def parse_primary():
        t = peek()
        if isinstance(t, float):
            return consume()
        if t == '(':
            consume('(')
            val = parse_expression()
            if peek() != ')':
                raise ValueError("Syntax error")
            consume(')')
            return val
        raise ValueError("Syntax error")

    result = parse_expression()
    if pos < len(tokens):
        raise ValueError("Syntax error")
    return result

def crc16_ccitt(data: bytes) -> int:
    crc = 0xFFFF
    for byte in data:
        crc ^= (byte << 8)
        for _ in range(8):
            if crc & 0x8000:
                crc = (crc << 1) ^ 0x1021
            else:
                crc = (crc << 1)
            crc &= 0xFFFF
    return crc

import math

class RunningStats:
    def __init__(self):
        self._count = 0
        self._mean = 0.0
        self._m2 = 0.0

    def add(self, x: float) -> None:
        self._count += 1
        delta = x - self._mean
        self._mean += delta / self._count
        delta2 = x - self._mean
        self._m2 += delta * delta2

    @property
    def count(self) -> int:
        return self._count

    @property
    def mean(self) -> float:
        if self._count == 0:
            return 0.0
        return self._mean

    @property
    def variance(self) -> float:
        if self._count < 2:
            return 0.0
        return self._m2 / (self._count - 1)

    @property
    def std(self) -> float:
        if self._count < 2:
            return 0.0
        return math.sqrt(self.variance)
